package com.foodieexpress.controller;
import com.foodieexpress.dto.*;import com.foodieexpress.model.*;import com.foodieexpress.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/support") @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')") public class AdminSupportController {
 private final SupportService support;private final AdminAuthorization authorization;
 public AdminSupportController(SupportService s,AdminAuthorization a){support=s;authorization=a;}
 @GetMapping("/tickets") public ResponseEntity<ApiResponse<List<SupportResponses.Ticket>>> tickets(@RequestHeader(value="X-Session-Token",required=false)String token,@RequestParam(required=false)SupportTicket.Status status,@RequestParam(required=false)String search){authorization.requireAdmin(token);return ResponseEntity.ok(ApiResponse.success("Support tickets",support.adminTickets(status,search)));}
 @GetMapping("/tickets/{id}") public ResponseEntity<ApiResponse<SupportResponses.Ticket>> ticket(@RequestHeader(value="X-Session-Token",required=false)String token,@PathVariable Long id){authorization.requireAdmin(token);return ResponseEntity.ok(ApiResponse.success("Support ticket",support.adminTicket(id)));}
 @PostMapping("/tickets/{id}/messages") public ResponseEntity<ApiResponse<SupportResponses.Ticket>> reply(@RequestHeader(value="X-Session-Token",required=false)String token,@PathVariable Long id,@Valid @RequestBody SupportRequests.Reply req){User admin=authorization.requireAdmin(token);return ResponseEntity.ok(ApiResponse.success("Reply sent",support.adminReply(id,admin,req.message())));}
 @PatchMapping("/tickets/{id}/status") public ResponseEntity<ApiResponse<SupportResponses.Ticket>> status(@RequestHeader(value="X-Session-Token",required=false)String token,@PathVariable Long id,@Valid @RequestBody SupportRequests.StatusUpdate req){User admin=authorization.requireAdmin(token);return ResponseEntity.ok(ApiResponse.success("Ticket status updated",support.updateStatus(id,admin,req.status(),req.note())));}
 @PatchMapping("/tickets/{id}/assignment") public ResponseEntity<ApiResponse<SupportResponses.Ticket>> assign(@RequestHeader(value="X-Session-Token",required=false)String token,@PathVariable Long id,@Valid @RequestBody SupportRequests.Assignment req){authorization.requireAdmin(token);return ResponseEntity.ok(ApiResponse.success("Ticket assigned",support.assign(id,req.adminId())));}
 @GetMapping("/admins") public ResponseEntity<ApiResponse<List<Map<String,Object>>>> admins(@RequestHeader(value="X-Session-Token",required=false)String token){authorization.requireAdmin(token);return ResponseEntity.ok(ApiResponse.success("Admins",support.admins()));}
 @GetMapping("/faqs") public ResponseEntity<ApiResponse<List<SupportResponses.Faq>>> faqs(@RequestHeader(value="X-Session-Token",required=false)String token){authorization.requireAdmin(token);return ResponseEntity.ok(ApiResponse.success("FAQs",support.adminFaqs()));}
 @PostMapping("/faqs") public ResponseEntity<ApiResponse<SupportResponses.Faq>> createFaq(@RequestHeader(value="X-Session-Token",required=false)String token,@Valid @RequestBody SupportRequests.Faq req){authorization.requireAdmin(token);return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("FAQ created",support.saveFaq(null,req)));}
 @PutMapping("/faqs/{id}") public ResponseEntity<ApiResponse<SupportResponses.Faq>> updateFaq(@RequestHeader(value="X-Session-Token",required=false)String token,@PathVariable Long id,@Valid @RequestBody SupportRequests.Faq req){authorization.requireAdmin(token);return ResponseEntity.ok(ApiResponse.success("FAQ updated",support.saveFaq(id,req)));}
 @DeleteMapping("/faqs/{id}") public ResponseEntity<ApiResponse<Void>> deleteFaq(@RequestHeader(value="X-Session-Token",required=false)String token,@PathVariable Long id){authorization.requireAdmin(token);support.deleteFaq(id);return ResponseEntity.ok(ApiResponse.success("FAQ deleted",null));}
}
